using namespace cinema;
using protocol::NodeRole;

static geometry::Point point(float x, float y) {
  return {static_cast<uint16_t>(x * 65535 + 0.5f), static_cast<uint16_t>(y * 65535 + 0.5f)};
}

// The center of a symmetric trapezoid has y=0.42, whereas a bilinear interpolation gives 0.5.
// This analytic case distinguishes a genuine projective mapping from a corner interpolation.
static void testHomography() {
  geometry::Quad quad{{point(.2f, .1f), point(.8f, .1f), point(.95f, .9f), point(.05f, .9f)}};
  geometry::Transform transform;
  assert(transform.begin(quad));
  const auto center = transform.map(32768, 32768);
  assert(std::abs(int(center.x) - 32768) <= 3 && std::abs(int(center.y) - int(.42f * 65535)) <= 4);
  const uint32_t coordinates[4][2]{{0, 0}, {65535, 0}, {65535, 65535}, {0, 65535}};
  for (uint8_t i = 0; i < 4; i++) {
    const auto projected = transform.map(coordinates[i][0], coordinates[i][1]);
    assert(std::abs(int(projected.x) - quad.points[i].x) <= 2 && std::abs(int(projected.y) - quad.points[i].y) <= 2);
  }
  // Rotated and mirrored semantic corner labels describe the same convex region and remain valid.
  const auto original = quad;
  for (uint8_t rotation = 0; rotation < 4; rotation++) {
    assert(transform.begin(quad));
    const auto first = quad.points[0];
    for (uint8_t i = 0; i < 3; i++) quad.points[i] = quad.points[i + 1];
    quad.points[3] = first;
  }
  quad = {{original.points[1], original.points[0], original.points[3], original.points[2]}};
  assert(transform.begin(quad));
  quad.points[1] = quad.points[0]; assert(!transform.begin(quad));
  quad = {{point(0, 0), point(1, 1), point(1, 0), point(0, 1)}}; assert(!transform.begin(quad));
  quad = {{point(0, 0), point(1, 0), point(.1f, .1f), point(0, 1)}}; assert(!transform.begin(quad));
  quad = {{point(0, 0), point(1, 0), point(1, .005f), point(0, .005f)}}; assert(!transform.begin(quad));

  stream::Config config{7, 4, 0, 0, 0};
  config.leftCalibration = original;
  uint8_t encoded[stream::CONFIG_SIZE];
  assert(stream::encodeConfig(config, encoded, sizeof(encoded), 100, 1024));
  stream::Config restored;
  assert(stream::decodeConfig(encoded, sizeof(encoded), &restored) && config == restored);
  std::vector<uint8_t> image(64 * 64 * 2);
  for (size_t y = 0; y < 64; y++) for (size_t x = 0; x < 64; x++) {
    const uint16_t value = ((x / 2) << 11) | (y << 5);
    image[(y * 64 + x) * 2] = value >> 8; image[(y * 64 + x) * 2 + 1] = value & 255;
  }
  uint8_t colors[6];
  assert(stream::sampleRgb565(config, NodeRole::CameraLeft, image.data(), image.size(), 64, 64, colors, sizeof(colors)));
  assert(colors[0] >= 78 && colors[0] <= 88 && colors[1] >= 28 && colors[1] <= 36);
}

// The production SPI endpoint repeats a photo chunk until the master advances its offset.
// Corrupt returns, stale duplicates, another camera, and a mid-photo reboot cannot mix images.
static void testPhotoTransport() {
  camera::SpiSlaveEndpoint left(NodeRole::CameraLeft), right(NodeRole::CameraRight);
  assert(left.begin() && right.begin());
  wled::CinemaController controller;
  wled::CinemaConfig config;
  config.enabled = true; config.generation = 7; config.topLeds = 4;
  bool corrupt = false;
  uint32_t time = 10000;
  cinemaTest::exchange = [&](bool isLeft, spi_transaction_t* transaction) {
    cinemaTest::slaveTransaction = transaction;
    (isLeft ? left : right).run();
    if (corrupt) { static_cast<uint8_t*>(transaction->rx_buffer)[12] ^= 1; corrupt = false; }
  };
  assert(controller.applyConfig(config)); controller.begin();
  auto poll = [&] { cinemaTest::nowMillis = time; controller.service(time); time += 16; };
  poll(); poll();
  wled::PreviewInfo info;
  assert(controller.preview().request(NodeRole::CameraLeft, time, &info));
  controller.preview().service(time - 1); // The HTTP task can publish a request after the loop sampled time.
  assert(controller.preview().info(&info) && info.state == wled::PreviewState::Capturing);
  assert(!controller.preview().request(NodeRole::CameraRight, time, &info));
  // Synthetic SOF fixture tests framing/bounds, not JPEG pixel decoding.
  std::vector<uint8_t> image(preview::MAX_IMAGE_SIZE - 13, 0);
  const uint8_t header[] = {0xFF,0xD8,0xFF,0xC0,0,17,8,1,0xE0,2,0x80,3,1,0x11,0,2,0x11,0,3,0x11,0};
  memcpy(image.data(), header, sizeof(header));
  image[image.size()-2] = 0xFF; image.back() = 0xD9;
  bool published = false;
  for (unsigned iteration = 0; iteration < 600; iteration++) {
    poll();
    for (auto endpoint : {&left, &right}) {
      stream::CaptureRequest current;
      if (!endpoint->captureRequest(&current)) continue;
      stream::Frame rgb;
      rgb.header.captureTimeUs = esp_timer_get_time();
      if (!current.requestForCapture(rgb.header.captureTimeUs, rgb.header.captureTimeUs, &rgb.header.pollSequence)) continue;
      rgb.header.configGeneration = current.config.generation;
      rgb.header.controllerBootId = current.controllerBootId;
      rgb.header.frameId = iteration + 1;
      rgb.header.slotCount = 2;
      rgb.colors[0] = rgb.colors[3] = 255;
      assert(endpoint->publishFrame(rgb));
    }
    stream::CaptureRequest request;
    if (!published && left.captureRequest(&request) && request.previewId != 0) {
      assert(left.publishPreview(request, image.data(), image.size(), preview::WIDTH, preview::HEIGHT));
      published = true;
      corrupt = true;
    }
    assert(controller.preview().info(&info));
    if (info.state == wled::PreviewState::Ready) break;
  }
  assert(info.state == wled::PreviewState::Ready && info.received == image.size() && info.size == image.size());
  assert(controller.cameraStatus(wled::CameraSide::Left).framesReceived > 10);
  assert(controller.cameraStatus(wled::CameraSide::Right).framesReceived > 10);
  uint8_t chunk[preview::CHUNK_SIZE]; size_t size = 0;
  for (uint16_t offset = 0; offset < image.size(); offset += preview::CHUNK_SIZE) {
    assert(controller.preview().read(info.id, offset, chunk, &size) && size == std::min<size_t>(preview::CHUNK_SIZE, image.size() - offset));
    assert(memcmp(chunk, image.data() + offset, size) == 0);
  }
  assert(!controller.preview().read(info.id + 1, 0, chunk, &size));
  assert(!controller.preview().read(info.id, 1, chunk, &size));
  assert(!controller.preview().read(info.id, preview::MAX_IMAGE_SIZE, chunk, &size));
  const uint32_t firstId = info.id;
  std::atomic<bool> readerStarted{false};
  std::thread reader([&] {
    uint8_t copied[preview::CHUNK_SIZE]; size_t copiedSize = 0;
    for (unsigned attempt = 0; attempt < 128; attempt++) {
      if (controller.preview().read(firstId, 0, copied, &copiedSize)) {
        assert(copiedSize == preview::CHUNK_SIZE && memcmp(copied, image.data(), copiedSize) == 0);
      }
      readerStarted.store(true);
    }
  });
  while (!readerStarted.load()) std::this_thread::yield();
  assert(controller.preview().request(NodeRole::CameraRight, time, &info));
  reader.join(); // Concurrent HTTP-sized copies never observe a different request's partial image.
  assert(info.id != firstId && !controller.preview().read(firstId, 0, chunk, &size));
  controller.preview().service(time + preview::CAPTURE_TIMEOUT_MS + 1);
  assert(controller.preview().info(&info) && info.state == wled::PreviewState::Failed);
  assert(controller.preview().request(NodeRole::CameraLeft, time, &info));
  const uint32_t id = info.id;
  uint8_t payload[preview::HEADER_SIZE + preview::CHUNK_SIZE]{};
  protocol::writeU32Le(payload, id); protocol::writeU32Le(payload + 4, 42);
  protocol::writeU32Le(payload + 8, image.size());
  protocol::writeU16Le(payload + 12, preview::WIDTH); protocol::writeU16Le(payload + 14, preview::HEIGHT);
  protocol::PacketView packet;
  packet.header.type = protocol::MessageType::SnapshotBegin;
  packet.header.source = NodeRole::CameraRight; packet.header.target = NodeRole::Controller; packet.header.bootId = 100;
  packet.payload = payload; packet.payloadSize = preview::METADATA_SIZE;
  assert(!controller.preview().accept(packet, 42)); // Wrong physical camera/role.
  packet.header.source = NodeRole::CameraLeft;
  assert(!controller.preview().accept(packet, 43)); // Old controller session.
  assert(controller.preview().accept(packet, 42));
  assert(controller.preview().accept(packet, 42)); // Duplicate metadata cannot reset progress.
  packet.header.type = protocol::MessageType::SnapshotChunk;
  packet.payloadSize = sizeof(payload);
  protocol::writeU16Le(payload + 8, 0); protocol::writeU16Le(payload + 10, preview::CHUNK_SIZE);
  memcpy(payload + preview::HEADER_SIZE, image.data(), preview::CHUNK_SIZE);
  assert(controller.preview().accept(packet, 42));
  assert(!controller.preview().accept(packet, 42)); // Duplicate chunk cannot advance twice.
  protocol::writeU16Le(payload + 8, preview::CHUNK_SIZE);
  packet.header.bootId++;
  assert(!controller.preview().accept(packet, 42));
  assert(controller.preview().info(&info) && info.state == wled::PreviewState::Failed);
  controller.preview().service(time + preview::RETENTION_MS + 1);
  assert(controller.preview().info(&info) && info.state == wled::PreviewState::Idle);
  controller._spiMaster.end(); left.end(); right.end(); cinemaTest::exchange = {};
  assert(cinemaTest::liveAllocations == 0);
}

int main() {
  testHomography(); testPhotoTransport();
  {
    wled::CinemaPreview firstBoot, secondBoot;
    wled::PreviewInfo first, second;
    assert(firstBoot.request(NodeRole::CameraLeft, 0, &first));
    assert(secondBoot.request(NodeRole::CameraLeft, 0, &second));
    assert(first.id != second.id); // Deterministic RNG stub models distinct boot seeds.
  }
  std::cout << "Cinema calibration checks passed: projective mapping, mirrored regions, bounded photo transport and recovery.\n";
}
